  notifyType: [{ required: true, message: '请输入通知类型（1版本更新 2系统故障 3系统维护 4资料下架 5日常滚动）', trigger: 'blur' }],
  title: [{ required: true, message: '请输入Title', trigger: 'blur' }],
};

function openCreate() {
  editingId.value = null;
  dirty.value = false;
  formState.notifyType = '';
  formState.title = '';
  formState.content = '';
  formState.status = '';
  formState.sort = undefined;
  formState.displayMode = '';
  formState.faultStartTime = '';
  formState.faultEndTime = '';
  formState.maintenanceStartTime = '';
  formState.maintenanceEndTime = '';
  formState.remindBeforeMinutes = undefined;
  formState.uploadUserId = undefined;
  formState.materialId = undefined;
  formState.materialTitleSnapshot = '';
  formState.publishStart = '';
  formState.publishEnd = '';
  formState.scrollTimeInterval = undefined;
  formState.createBy = '';
  formState.createTime = '';
  formState.updateBy = '';
  formState.updateTime = '';
  formState.remark = '';
  modalOpen.value = true;
}

async function openEdit(record: Notification) {
  editingId.value = record.notifyId;
  dirty.value = false;
  formState.notifyType = record.notifyType;
  formState.title = record.title;
  formState.content = record.content;
  formState.status = record.status;
  formState.sort = record.sort;
  formState.displayMode = record.displayMode;
  formState.faultStartTime = record.faultStartTime;
  formState.faultEndTime = record.faultEndTime;
  formState.maintenanceStartTime = record.maintenanceStartTime;
  formState.maintenanceEndTime = record.maintenanceEndTime;
  formState.remindBeforeMinutes = record.remindBeforeMinutes;
  formState.uploadUserId = record.uploadUserId;
  formState.materialId = record.materialId;
  formState.materialTitleSnapshot = record.materialTitleSnapshot;
  formState.publishStart = record.publishStart;
  formState.publishEnd = record.publishEnd;
  formState.scrollTimeInterval = record.scrollTimeInterval;
  formState.createBy = record.createBy;
  formState.createTime = record.createTime;
  formState.updateBy = record.updateBy;
  formState.updateTime = record.updateTime;
  formState.remark = record.remark;
  modalOpen.value = true;
}

function requestClose() {
  if (!dirty.value) {
    modalOpen.value = false;
    return;
  }
  Modal.confirm({
    title: '放弃修改？',
    content: '当前表单有未保存的修改。',
    okText: '放弃',
    okType: 'danger',
    cancelText: '继续编辑',
    onOk: () => {
      dirty.value = false;
      modalOpen.value = false;
    },
  });
}

function markDirty() {
  if (modalOpen.value) {
    dirty.value = true;
  }
}

async function submit() {
  try {
    await formRef.value?.validate();
  } catch {
    return;
  }
  submitting.value = true;
  try {
    const payload = {
      notifyType: formState.notifyType,
      title: formState.title,
      content: formState.content,
      status: formState.status,
      sort: formState.sort,
      displayMode: formState.displayMode,
      faultStartTime: formState.faultStartTime,
      faultEndTime: formState.faultEndTime,
      maintenanceStartTime: formState.maintenanceStartTime,
      maintenanceEndTime: formState.maintenanceEndTime,
      remindBeforeMinutes: formState.remindBeforeMinutes,
      uploadUserId: formState.uploadUserId,
      materialId: formState.materialId,
      materialTitleSnapshot: formState.materialTitleSnapshot,
      publishStart: formState.publishStart,
      publishEnd: formState.publishEnd,
      scrollTimeInterval: formState.scrollTimeInterval,
      createBy: formState.createBy,
      createTime: formState.createTime,
      updateBy: formState.updateBy,
      updateTime: formState.updateTime,
      remark: formState.remark,
    } as NotificationPayload;
    if (editingId.value === null) {
      await createNotification(payload);
      message.success('新增成功');
    } else {
      await updateNotification(editingId.value, payload);
      message.success('修改成功');
    }
    modalOpen.value = false;
    dirty.value = false;
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '提交失败');
  } finally {
    submitting.value = false;
  }
}

async function remove(record: Notification) {
  try {
    await deleteNotification(record.notifyId);
    message.success('删除成功');
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '删除失败');
  }
}

onMounted(() => {
  void fetchList();
});
</script>
